function majority(nums) {
  var candidate = null;
  var count = 0;
  nums.forEach(function (n) {
    if (count === 0) {
      candidate = n;
    }
    count += n === candidate ? 1 : -1;
  });
  return candidate;
}

console.log(majority([2, 2, 1, 1, 1, 2, 2]));
console.log(majority([3, 3, 4]));
